trace=project/'.aris/traces/experiment-bridge/2026-10-03_anytoany49'
checks=[]
def record(name, detail): checks.append(dict(name=name,status='PASS',detail=detail))
def tree(name): return ast.parse((project/name).read_text(encoding='utf-8'))
def function(name, target): return next(n for n in tree(name).body if isinstance(n, ast.FunctionDef) and n.name==target)
def run_nodes(nodes, env): exec(compile(ast.fix_missing_locations(ast.Module(body=nodes,type_ignores=[])),'<review-ast>','exec'),env)

missing=next(n for n in tree('missing_evaluation.py').body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='MISSING' for t in n.targets))
masks=ast.literal_eval(missing.value)
main=function('missing_anytoany_development.py','main')
core=[n for n in main.body if 84<=n.lineno<=98]
class Bank:
    def __init__(self, retained, positions): self.retained=retained;self.positions=positions;self.shape=(len(positions),11)
    def __getitem__(self, ix): return Bank(self.retained,[self.positions[i] for i in ix])
dev=['image0','image1','image2','image3'];query=[0,2];clean=Bank('RNT',list(range(4)))
encodings=[];pairs=[];distance_calls=[];saved_distance=object()
def extract(model, records, cfg, seed, missing):
    assert records is dev and seed==42
    keep=''.join(letter for letter,key in zip('RNT',('RGB','NI','TI')) if key not in missing)
    encodings.append(dict(retained=keep,missing=list(missing),records=records))
    return Bank(keep,list(range(4))),{'triplets':4}
def distance(q,g):
    assert q.positions==query and g.positions==list(range(4))
    distance_calls.append((q.retained,g.retained));return (q.retained,g.retained)
def measure(name, distances, missing_q, missing_g):
    q,g=name[2:].split('_g_')
    assert missing_q==[k for l,k in zip('RNT',('RGB','NI','TI')) if l not in q]
    assert missing_g==[k for l,k in zip('RNT',('RGB','NI','TI')) if l not in g]
    assert distances is saved_distance if q==g=='RNT' else distances==(q,g)
    pairs.append((q,g));env['measurements'][name]={}
env=dict(clean=clean,MISSING=masks,dev=dev,query=query,model=object(),cfg=object(),arguments=NS(seed=42),
         extract_missing=extract,torch=NS(isfinite=lambda x:NS(all=lambda:True)),
         saved={'distances':saved_distance},measurements={},diagnostics={},measure=measure,distance=distance)
run_nodes(core,env)
sets={'R','N','T','RN','RT','NT','RNT'}
assert set(pairs)==set(itertools.product(sets,repeat=2)) and len(pairs)==49 and len(distance_calls)==48
assert len(encodings)==6 and {r['retained'] for r in encodings}==sets-{'RNT'}
assert len({id(v) for v in env['features'].values()})==7
record('actual_AST_49_cartesian_and_labels',{'pairs':len(pairs),'new_missing_encodings':len(encodings),'total_banks':7,'new_distance_calls':48,'saved_clean_distances_exact_object':True,'retained_to_missing':{k:list(v) for k,v in env['availability'].items()}})

mask_fn=function('missing_evaluation.py','mask_images')
mask_env={'torch':NS(zeros_like=lambda value:[0]*len(value))};run_nodes([mask_fn],mask_env)
images={'RGB':[1,2],'NI':[3,4],'TI':[5,6]}
for missing in masks.values():
    masked=mask_env['mask_images'](images,missing)
    assert all(masked[k]==([0,0] if k in missing else images[k]) for k in images)
    assert all(masked[k] is images[k] for k in images if k not in missing)
record('actual_mask_function_normalized_zero',{'six_masks':6,'retained_inputs_identity_preserved':True})

class MemoryFS:
    def __init__(self): self.files={};self.dirs={'/','/out','/train'}
    def path(self,v): return MemoryPath(self,v)
class MemoryPath:
    def __init__(self,fs,v): self.fs=fs;self.key=str(v).replace('\\','/')
    def __truediv__(self,v): return MemoryPath(self.fs,str(PurePosixPath(self.key)/str(v)))
    def __str__(self): return self.key
    def __repr__(self): return repr(self.key)
    @property
    def name(self): return PurePosixPath(self.key).name
    @property
    def parent(self): return MemoryPath(self.fs,str(PurePosixPath(self.key).parent))
    def exists(self): return self.key in self.fs.files or self.key in self.fs.dirs
    def mkdir(self,exist_ok=False,parents=False):
        if self.exists() and not exist_ok: raise FileExistsError(self.key)
        self.fs.dirs.add(self.key)
    def read_bytes(self): return self.fs.files[self.key]
    def read_text(self,encoding=None): return self.read_bytes().decode(encoding or 'utf-8')
    def write_bytes(self,b): self.fs.files[self.key]=b;return len(b)
    def stat(self): return NS(st_size=len(self.read_bytes()))
    def open(self,mode):
        assert mode=='x'
        if self.exists(): raise FileExistsError(self.key)
        self.fs.files[self.key]=b''
        return NSContext(self)
class NSContext:
    def __init__(self,value):self.value=value
    def __enter__(self):return self.value
    def __exit__(self,*args):return False

def dump(path,obj):path.write_bytes(json.dumps(obj).encode())
launch_main=function('launch_anytoany_frozen.py','main')
slot=next(n for n in launch_main.body if isinstance(n,ast.FunctionDef) and n.name=='slot')
job_assign=next(n for n in launch_main.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='jobs' for t in n.targets))
jobs=ast.literal_eval(job_assign.value)
assert jobs==[('MSVR310',0),('RGBNT201',2),('RGBNT100',3)]
record('actual_controller_schedule',{'jobs':jobs,'preserved_gpu1':True,'workers':3})

def controller_case(variant,dataset='MSVR310',gpu=0,fault=None):
    fs=MemoryFS();output=fs.path('/out');name=dataset+'_'+variant+'_s42';run=fs.path('/train')/name
    exit_path=run/'exit.json' if variant=='demo' else run.parent/(name+'_exit.json')
    inputs=[run/'best.pth',run/'best_dev_arrays.npz',run/'result.json',exit_path]
    terminal=dict(status='COMPLETE',epochs=50,arguments=dict(dataset=dataset,variant=variant,seed=42))
    if fault=='terminal_status':terminal['status']='RUNNING'
    if fault=='terminal_epochs':terminal['epochs']=49
    if fault=='wrong_variant':terminal['arguments']['variant']='other'
    if fault=='wrong_dataset':terminal['arguments']['dataset']='other'
    dump(run/'result.json',terminal);dump(exit_path,{'exit_code':1 if fault=='training_exit' else 0})
    (run/'best.pth').write_bytes(b'checkpoint');(run/'best_dev_arrays.npz').write_bytes(b'arrays')
    children=[];idle_calls=[]
    def spawn(argv,stdout,stderr,env):
        smoke='--smoke' in argv;stage='smoke' if smoke else 'full';folder=fs.path(argv[argv.index('--output')+1])
        assert env['CUDA_VISIBLE_DEVICES']==str(gpu)
        assert env['OMP_NUM_THREADS']==env['MKL_NUM_THREADS']==env['OPENBLAS_NUM_THREADS']=='4'
        assert argv[2]=='missing_anytoany_development.py'
        result=dict(status='PASS' if smoke else 'COMPLETE',optimizer_updates=0,state_tensor_versions_unchanged=True,normal_feature_max_error=0,measurements={str(i):{} for i in range(49)})
        if smoke and fault in ('smoke_status','updates','versions','parity'):
            key,value={'smoke_status':('status','FAIL'),'updates':('optimizer_updates',1),'versions':('state_tensor_versions_unchanged',False),'parity':('normal_feature_max_error',1e-7)}[fault];result[key]=value
        if not smoke and fault=='full48':result['measurements'].pop('48')
        dump(folder/('smoke.json' if smoke else 'result.json'),result)
        children.append((stage,argv))
        def wait():
            if smoke and fault and fault.startswith('mutate_'):
                path=inputs[int(fault.split('_')[1])];path.write_bytes(path.read_bytes()+b'changed')
            return 1 if (smoke and fault=='smoke_exit') or (not smoke and fault=='full_exit') else 0
        return NS(pid=100+len(children),wait=wait)
    env=dict(args=NS(training_root='/train',variant=variant,data_root='/data',pretrained='/clip'),output=output,Path=fs.path,
             json=json,hashlib=hashlib,write_json=dump,idle=idle_calls.append,sys=NS(executable='/python'),time=NS(time=lambda:1),
             os=NS(environ={}),subprocess=NS(Popen=spawn,STDOUT=-2))
    run_nodes([slot],env)
    error=None
    try:env['slot']((dataset,gpu))
    except AssertionError:error='AssertionError'
    if fault:
        assert error=='AssertionError',fault
        expected=0 if fault in ('training_exit','terminal_status','terminal_epochs','wrong_variant','wrong_dataset') else 2 if fault in ('full48','full_exit') else 1
        assert len(children)==expected,(fault,len(children))
        assert not (output/name/'controller_result.json').exists()
    else:
        assert error is None and [row[0] for row in children]==['smoke','full']
        assert idle_calls==[gpu,gpu]
        assert json.loads((output/name/'controller_result.json').read_text())['status']=='PASS'
    return {'variant':variant,'dataset':dataset,'gpu':gpu,'fault':fault,'spawn_count':len(children),'result':'rejected' if fault else 'smoke_then_full'}
controller=[]
for variant in ('demo','axis_mass_fullref'):
    for ds,gpu in jobs:controller.append(controller_case(variant,ds,gpu))
    for fault in ('training_exit','terminal_status','terminal_epochs','wrong_variant','wrong_dataset','smoke_exit','smoke_status','updates','versions','parity','mutate_0','mutate_1','mutate_2','mutate_3','full48','full_exit'):
        controller.append(controller_case(variant,fault=fault))
record('actual_controller_slot_AST_mocks',{'cases':len(controller),'results':controller,'NN_executed':False,'real_subprocesses':0})

